head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > isString]<br/>전달된 값의 타입이 String 인지 판별하여 결과를 반환합니다.",
    "validation" : [
        "value(필수) 파라미터로 타입을 검사할 값을 설정할 수 있어야 합니다.",
        "value 파라미터의 타입이 String 이면 true 를 반환해야 합니다.",
        "value 파라미터의 타입이 String 이 아니면 false 를 반환해야 합니다.",
        "value 파라미터가 null 또는 undefined 이면 false 를 반환해야 합니다.",
        "숫자로 된 문자열(예: '12')도 String 타입이므로 true 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_isString_string_onclick = function () {
    let ret = WebSquare.util.isString("abc");
    wf_body_bottom.getObj("scwin").setReturnValue("isString('abc') : " + ret);
}

scwin.btn_isString_numstring_onclick = function () {
    let ret = WebSquare.util.isString("12");
    wf_body_bottom.getObj("scwin").setReturnValue("isString('12') : " + ret);
}

scwin.btn_isString_number_onclick = function () {
    let ret = WebSquare.util.isString(12);
    wf_body_bottom.getObj("scwin").setReturnValue("isString(12) : " + ret);
}

scwin.btn_isString_boolean_onclick = function () {
    let ret = WebSquare.util.isString(true);
    wf_body_bottom.getObj("scwin").setReturnValue("isString(true) : " + ret);
}

scwin.btn_isString_null_onclick = function () {
    let ret = WebSquare.util.isString(null);
    wf_body_bottom.getObj("scwin").setReturnValue("isString(null) : " + ret);
}

scwin.btn_isString_undefined_onclick = function () {
    let ret = WebSquare.util.isString(undefined);
    wf_body_bottom.getObj("scwin").setReturnValue("isString(undefined) : " + ret);
}

scwin.btn_isString_empty_onclick = function () {
    let ret = WebSquare.util.isString("");
    wf_body_bottom.getObj("scwin").setReturnValue("isString('') : " + ret);
}
